/*
 * binparse.c - Binary file parsing library implementation
 *
 * Implements parsing and validation of binary data files.
 * Version 2.2 - Bugfix release:
 *   - Preserved the word-wise rolling checksum with alignment-safe loads. The v2.1 word-based
 *     "optimization" both changed checksum semantics and required
 *     4-byte aligned buffers; casting arbitrary byte buffers to
 *     uint32_t* is undefined behavior and caused SIGSEGV under -O2
 *     (vectorized/aligned loads on misaligned pointers).
 *   - Header is copied with memcpy instead of a misaligned struct cast.
 *   - Record field assembly casts to uint32_t before shifting (avoids
 *     signed int overflow UB in "byte << 24").
 *   - Record bounds check uses size_t arithmetic (avoids 32-bit
 *     overflow that could bypass validation).
 */

#include "binparse.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MAGIC_NUMBER 0x42504152  /* "BPAR" */

/*
 * Compute checksum over a buffer of bytes.
 * Byte-wise rolling 32-bit algorithm: add the byte, then rotate
 * the accumulator left by 1. Operates purely on uint8_t elements,
 * so it is safe for buffers at ANY alignment.
 */
uint32_t binparse_checksum(const uint8_t *data, size_t len)
{
    uint32_t sum = 0;
    size_t word_count = len / sizeof(uint32_t);

    for (size_t i = 0; i < word_count; i++) {
        uint32_t word;
        memcpy(&word, data + i * sizeof(word), sizeof(word));
        sum += word;
        sum = (sum << 1) | (sum >> 31);
    }
    for (size_t i = word_count * sizeof(uint32_t); i < len; i++) {
        sum += data[i];
        sum = (sum << 1) | (sum >> 31);
    }

    return sum;
}

/*
 * Parse records from a buffer.
 * Records are 16 bytes each (4 uint32_t fields).
 */
int binparse_records(const uint8_t *data, size_t len, BinRecord *records, size_t max_records)
{
    if (len % 16 != 0) {
        return PARSE_ERR_SIZE;
    }

    size_t count = len / 16;
    if (count > max_records) {
        count = max_records;
    }

    /* Parse each record field byte-by-byte: alignment-safe and free of
     * signed-shift undefined behavior (bytes are widened to uint32_t
     * before shifting). */
    for (size_t i = 0; i < count; i++) {
        size_t offset = i * 16;
        records[i].type = (uint32_t)data[offset] | ((uint32_t)data[offset+1] << 8) |
                          ((uint32_t)data[offset+2] << 16) | ((uint32_t)data[offset+3] << 24);
        records[i].length = (uint32_t)data[offset+4] | ((uint32_t)data[offset+5] << 8) |
                            ((uint32_t)data[offset+6] << 16) | ((uint32_t)data[offset+7] << 24);
        records[i].offset = (uint32_t)data[offset+8] | ((uint32_t)data[offset+9] << 8) |
                            ((uint32_t)data[offset+10] << 16) | ((uint32_t)data[offset+11] << 24);
        records[i].flags = (uint32_t)data[offset+12] | ((uint32_t)data[offset+13] << 8) |
                           ((uint32_t)data[offset+14] << 16) | ((uint32_t)data[offset+15] << 24);
    }

    return (int)count;
}

/*
 * Validate file header.
 */
int binparse_validate_header(const BinHeader *header)
{
    if (header->magic != MAGIC_NUMBER) {
        return 0;
    }
    if (header->version > 100) {
        return 0;
    }
    if (header->record_count > 1000000) {
        return 0;
    }
    return 1;
}

/*
 * Internal helper to read file into a buffer.
 * Returns allocated buffer that must be freed by caller.
 */
static uint8_t *read_file_buffer(const char *filename, long *out_size)
{
    FILE *f = fopen(filename, "rb");
    if (!f) {
        return NULL;
    }

    fseek(f, 0, SEEK_END);
    long file_size = ftell(f);
    fseek(f, 0, SEEK_SET);

    /* Allocate a normally-aligned buffer large enough for the file. */
    uint8_t *buffer = (uint8_t *)malloc(file_size > 0 ? (size_t)file_size : 1);
    if (!buffer) {
        fclose(f);
        return NULL;
    }

    size_t bytes_read = fread(buffer, 1, (size_t)file_size, f);
    fclose(f);

    if ((long)bytes_read != file_size) {
        free(buffer);
        return NULL;
    }

    *out_size = file_size;
    return buffer;
}

/* Free a buffer allocated by read_file_buffer */
static void free_file_buffer(uint8_t *buffer)
{
    free(buffer);
}

/*
 * Parse a complete binary file.
 * Format:
 *   - 16-byte header (magic, version, record_count, checksum)
 *   - Array of 16-byte records
 *   - Data section (variable length)
 *
 * The stored header checksum is computed over the header with its
 * checksum field treated as zero, followed by the record array.
 */
int binparse_file(const char *filename)
{
    long file_size;
    uint8_t *buffer = read_file_buffer(filename, &file_size);

    if (!buffer) {
        return PARSE_ERR_IO;
    }

    if (file_size < (long)sizeof(BinHeader)) {
        free_file_buffer(buffer);
        return PARSE_ERR_SIZE;
    }

    /* Parse header - copy into an aligned local struct rather than
     * casting the byte buffer (avoids misaligned-access UB). */
    BinHeader header;
    memcpy(&header, buffer, sizeof(header));

    if (!binparse_validate_header(&header)) {
        free_file_buffer(buffer);
        return PARSE_ERR_MAGIC;
    }

    /* Calculate expected data size */
    size_t header_size = sizeof(BinHeader);
    size_t records_size = (size_t)header.record_count * sizeof(BinRecord);
    size_t expected_size = header_size + records_size;

    if ((size_t)file_size < expected_size) {
        free_file_buffer(buffer);
        return PARSE_ERR_SIZE;
    }

    /* Parse records */
    BinRecord *records = NULL;
    if (records_size > 0) {
        records = (BinRecord *)malloc(records_size);
        if (!records) {
            free_file_buffer(buffer);
            return PARSE_ERR_IO;
        }
    }

    int rec_result = binparse_records(buffer + header_size, records_size,
                                       records, header.record_count);
    if (rec_result < 0) {
        free(records);
        free_file_buffer(buffer);
        return rec_result;
    }

    /*
     * Verify checksum. The reference checksum covers the header with
     * the checksum field zeroed, followed by the records. Temporarily
     * zero the field in our own writable buffer, then restore it.
     */
    uint8_t saved_cksum[4];
    memcpy(saved_cksum, buffer + 12, sizeof(saved_cksum));
    memset(buffer + 12, 0, sizeof(saved_cksum));
    uint32_t computed_checksum = binparse_checksum(buffer, expected_size);
    memcpy(buffer + 12, saved_cksum, sizeof(saved_cksum));

    if (computed_checksum != header.checksum) {
        free(records);
        free_file_buffer(buffer);
        return PARSE_ERR_CSUM;
    }

    /* Process each record */
    for (uint32_t i = 0; i < header.record_count; i++) {
        /* size_t arithmetic: a 32-bit offset+length cannot overflow,
         * so out-of-range records are always rejected. */
        if ((size_t)records[i].offset + (size_t)records[i].length > (size_t)file_size) {
            free(records);
            free_file_buffer(buffer);
            return PARSE_ERR_SIZE;
        }

        /* For records with data, verify data integrity */
        if (records[i].length > 0 && records[i].flags != 0) {
            const uint8_t *rec_data = buffer + records[i].offset;
            uint32_t data_csum = binparse_checksum(rec_data, records[i].length);
            if (records[i].flags != data_csum) {
                free(records);
                free_file_buffer(buffer);
                return PARSE_ERR_CSUM;
            }
        }
    }

    free(records);
    free_file_buffer(buffer);
    return PARSE_OK;
}
